using MunicipalPlatform.Api.Platform.Tenancy;
namespace MunicipalPlatform.Api.Modules.Operations.Domain;

public sealed class LinkCheck : ITenantEntity { private LinkCheck() { } public LinkCheck(Guid municipalityId, string url) { Id = Guid.NewGuid(); MunicipalityId = municipalityId; Url = url.Trim(); State = "UNKNOWN"; CreatedAt = DateTimeOffset.UtcNow; } public Guid Id { get; private set; } public Guid MunicipalityId { get; private set; } public string Url { get; private set; } = string.Empty; public int? StatusCode { get; private set; } public string State { get; private set; } = string.Empty; public DateTimeOffset? CheckedAt { get; private set; } public long? LatencyMilliseconds { get; private set; } public string? FailureReason { get; private set; } public int ConsecutiveFailures { get; private set; } public DateTimeOffset CreatedAt { get; private set; } public void RecordSuccess(int statusCode, long latencyMs, DateTimeOffset now) { StatusCode = statusCode; LatencyMilliseconds = latencyMs; CheckedAt = now; FailureReason = null; ConsecutiveFailures = 0; State = statusCode < 400 ? "HEALTHY" : "DEGRADED"; } public void RecordFailure(string reason, DateTimeOffset now) { CheckedAt = now; FailureReason = reason; ConsecutiveFailures++; State = ConsecutiveFailures >= 3 ? "UNAVAILABLE" : "DEGRADED"; } }
